'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createArchive']);
const { createArchive } = api;

const archive = createArchive();
assert.deepStrictEqual(archive.listDocuments(), []);
const data = { id: 'd1', title: 'First', notes: 'note' };
const created = archive.createDocument(data);
assert.deepStrictEqual(created, {
  id: 'd1', title: 'First', notes: 'note', contributors: [], attachments: []
});
assert.deepStrictEqual(data, { id: 'd1', title: 'First', notes: 'note' });
created.title = 'corrupt';
created.contributors.push({ id: 'x', name: 'X' });
assert.strictEqual(archive.getDocument('d1').title, 'First');
assert.deepStrictEqual(archive.getDocument('d1').contributors, []);
assert.deepStrictEqual(archive.createDocument({ id: 'd2', title: 'Second' }), {
  id: 'd2', title: 'Second', notes: '', contributors: [], attachments: []
});
assert.deepStrictEqual(archive.listDocuments().map(d => d.id), ['d1', 'd2']);
assert.throws(() => archive.createDocument({ id: 'd1', title: 'Duplicate' }),
  { name: 'Error', message: 'Document exists' });

const contributor = { id: 'c1', name: 'Ada' };
let snapshot = archive.addContributor('d1', contributor);
assert.deepStrictEqual(snapshot.contributors, [{ id: 'c1', name: 'Ada' }]);
contributor.name = 'changed';
snapshot.contributors[0].name = 'also changed';
assert.deepStrictEqual(archive.getDocument('d1').contributors, [{ id: 'c1', name: 'Ada' }]);
archive.addContributor('d1', { id: 'c2', name: 'Grace' });
assert.throws(() => archive.addContributor('d1', { id: 'c1', name: 'Other' }),
  { name: 'Error', message: 'Item exists' });
assert.strictEqual(archive.removeContributor('d1', 'missing'), false);
assert.strictEqual(archive.removeContributor('d1', 'c1'), true);
assert.strictEqual(archive.removeContributor('d1', 'c1'), false);
assert.deepStrictEqual(archive.getDocument('d1').contributors, [{ id: 'c2', name: 'Grace' }]);

const attachment = { id: 'a1', label: 'PDF' };
snapshot = archive.addAttachment('d1', attachment);
attachment.label = 'changed';
snapshot.attachments[0].label = 'changed';
archive.addAttachment('d1', { id: 'a2', label: 'Image' });
assert.deepStrictEqual(archive.listAttachments('d1'), [
  { id: 'a1', label: 'PDF' }, { id: 'a2', label: 'Image' }
]);
const attachments = archive.listAttachments('d1');
attachments[0].label = 'bad';
attachments.push({ id: 'a3', label: 'bad' });
assert.deepStrictEqual(archive.listAttachments('d1'), [
  { id: 'a1', label: 'PDF' }, { id: 'a2', label: 'Image' }
]);
assert.throws(() => archive.addAttachment('d1', { id: 'a1', label: 'Again' }),
  { name: 'Error', message: 'Item exists' });
assert.strictEqual(archive.removeAttachment('d1', 'none'), false);
assert.strictEqual(archive.removeAttachment('d1', 'a1'), true);

assert.deepStrictEqual(archive.updateDocument('d1', {}), archive.getDocument('d1'));
assert.strictEqual(archive.updateDocument('d1', { title: 'Updated' }).title, 'Updated');
assert.strictEqual(archive.updateDocument('d1', { notes: '' }).notes, '');
for (const changes of [null, [], { title: '' }, { title: ' ' }, { notes: 1 },
  { id: 'x' }, { contributors: [] }, { attachments: [] }, { extra: true }]) {
  assert.throws(() => archive.updateDocument('d1', changes),
    { name: 'TypeError', message: 'Invalid changes' });
}
assert.strictEqual(archive.getDocument('d1').title, 'Updated');

for (const record of [null, [], {}, { id: '', title: 'T' }, { id: 'x', title: '' },
  { id: 'x', title: 'T', notes: 1 }]) {
  assert.throws(() => archive.createDocument(record), { name: 'TypeError', message: 'Invalid record' });
}
for (const record of [null, [], {}, { id: '', name: 'N' }, { id: 'c', name: '' }]) {
  assert.throws(() => archive.addContributor('d1', record), { name: 'TypeError', message: 'Invalid record' });
}
for (const record of [null, [], {}, { id: '', label: 'L' }, { id: 'a', label: '' }]) {
  assert.throws(() => archive.addAttachment('d1', record), { name: 'TypeError', message: 'Invalid record' });
}
for (const operation of [
  () => archive.getDocument('missing'),
  () => archive.addContributor('missing', { id: 'c', name: 'N' }),
  () => archive.removeContributor('missing', 'c'),
  () => archive.addAttachment('missing', { id: 'a', label: 'L' }),
  () => archive.removeAttachment('missing', 'a'),
  () => archive.updateDocument('missing', {}),
  () => archive.listAttachments('missing')
]) assert.throws(operation, { name: 'Error', message: 'Document not found' });

assert.strictEqual(archive.deleteDocument('missing'), false);
assert.strictEqual(archive.deleteDocument('d1'), true);
assert.strictEqual(archive.deleteDocument('d1'), false);
assert.deepStrictEqual(archive.listDocuments().map(d => d.id), ['d2']);
const independent = createArchive();
assert.deepStrictEqual(independent.listDocuments(), []);
independent.createDocument({ id: 'd1', title: 'Independent' });
assert.strictEqual(independent.getDocument('d1').title, 'Independent');

